 if(section==="Team & Users")return <><div className="kpi-grid compact-kpis">{[{label:"Active members",value:"24",icon:Users,tone:"blue"},{label:"Pending invites",value:"3",icon:Clock3,tone:"amber"},{label:"Teams",value:"5",icon:Boxes,tone:"violet"},{label:"Projects",value:"12",icon:Target,tone:"green"}].map(k=><div className="kpi-card compact" key={k.label}><div className={`kpi-icon ${k.tone}`}><k.icon size={17}/></div><span className="kpi-label">{k.label}</span><strong>{k.value}</strong></div>)}</div><div className="panel project-list-panel"><div className="panel-head"><div><h2>Workspace members</h2><p>Manage roles, project access, and invitations</p></div><button className="button primary" onClick={onCreate}><Plus size={15}/> Invite member</button></div><div className="project-table-wrap"><table><thead><tr><th>MEMBER</th><th>ROLE</th><th>TEAM</th><th>PROJECTS</th><th>STATUS</th><th>LAST ACTIVE</th></tr></thead><tbody>{[["Arun Singh","AS","Administrator","Platform","8","Active","Now"],["Riya Mehta","RM","Project Manager","Product","4","Active","12 min ago"],["Dev Kumar","DK","Developer","Platform","3","Active","38 min ago"],["Priya Shah","PS","Tester","Quality","5","Active","1 hour ago"],["Sanjay Rao","SR","Code Reviewer","Platform","6","Active","3 hours ago"]].map(r=><tr key={r[0]}><td><div className="project-cell"><div className="avatar">{r[1]}</div><strong>{r[0]}</strong></div></td><td>{r[2]}</td><td>{r[3]}</td><td>{r[4]}</td><td><Pill tone="green">{r[5]}</Pill></td><td>{r[6]}</td></tr>)}</tbody></table></div></div></>
