 if(section==="Audit Logs")return <><div className="toolbar panel"><label className="table-search"><Search size={15}/><input placeholder="Search audit events..." value={filter} onChange={e=>setFilter(e.target.value)}/></label><select><option>All actions</option><option>Authentication</option><option>Changes</option></select><select><option>All results</option><option>Success</option><option>Failure</option></select><button className="button secondary"><Filter size={14}/> Filters</button></div><div className="panel project-list-panel"><div className="project-table-wrap"><table><thead><tr><th>USER</th><th>ACTION</th><th>RESOURCE</th><th>TIMESTAMP</th><th>IP ADDRESS</th><th>RESULT</th></tr></thead><tbody>{[["Arun Singh","Updated requirement","REQ-042 · Profile management","Nov 16, 10:32 AM","192.0.2.18","Success"],["Riya Mehta","Approved pull request","PR #248 · citizen-portal-frontend","Nov 16, 10:18 AM","192.0.2.41","Success"],["Dev Kumar","Started verification","Citizen Service Portal","Nov 16, 09:54 AM","192.0.2.56","Success"],["System","Failed login attempt","Workspace authentication","Nov 15, 08:41 PM","192.0.2.99","Blocked"]].filter(r=>r[1].toLowerCase().includes(filter.toLowerCase())||r[2].toLowerCase().includes(filter.toLowerCase())).map(r=><tr key={r[1]}><td>{r[0]}</td><td>{r[1]}</td><td>{r[2]}</td><td>{r[3]}</td><td><code>{r[4]}</code></td><td><Pill tone={r[5]==="Success"?"green":"red"}>{r[5]}</Pill></td></tr>)}</tbody></table></div></div><div className="info-callout"><LockKeyhole size={15}/> IP addresses shown are reserved example addresses. This is demo audit data.</div></>
