function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}) { return <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-head"><h2 id="modal-title">{title}</h2><button className="icon-btn" aria-label="Close dialog" onClick={onClose}><X size={17}/></button></div>{children}</section></div> }

export default function NexusApp() {
 const [section,setSection]=useState("Dashboard"),[collapsed,setCollapsed]=useState(false),[dark,setDark]=useState(false),[modal,setModal]=useState(false),[projectName,setProjectName]=useState(""),[created,setCreated]=useState<string[]>([]),[toast,setToast]=useState("")
 const select=(value:string)=>{setSection(value);document.querySelector(".content-shell")?.scrollTo({top:0,behavior:"smooth"})}
 const showToast=(message:string)=>{setToast(message);window.setTimeout(()=>setToast(""),3200)}
 const [progress,setProgress]=useState(false)
 const startVerification=()=>{setProgress(true);showToast("Verification started in demo mode — no code was executed.");window.setTimeout(()=>setProgress(false),4500)}
 return <div className={`app-shell ${dark?"dark-mode":""}`}><Sidebar active={section} onSelect={select} collapsed={collapsed} onCollapse={()=>setCollapsed(!collapsed)}/><main className="main-shell"><Topbar section={section} onSelect={select} dark={dark} setDark={setDark}/><div className="content-shell"><PageContent key={section} section={section} onSelect={select} onCreate={()=>setModal(true)} onVerify={startVerification}/>{created.length>0&&<div className="sr-only" aria-live="polite">{created.length} projects created</div>}{progress&&<div className="progress-toast"><div className="toast-spinner"/><div><strong>Verification queued</strong><small>Simulation only · backend worker not connected</small></div><button aria-label="Dismiss" onClick={()=>setProgress(false)}><X size={15}/></button></div>}</div></main>{toast&&<div className="toast-message"><Check size={15}/>{toast}<button onClick={()=>setToast("")} aria-label="Dismiss"><X size={14}/></button></div>}{modal&&<Modal title={section==="Projects"||section==="Dashboard"?"Create project":section==="Team & Users"?"Invite team member":`Create ${section.toLowerCase()}`} onClose={()=>setModal(false)}><form onSubmit={e=>{e.preventDefault();const name=projectName.trim();if(!name){showToast("Enter a name to continue.");return}if(section==="Projects"||section==="Dashboard"){setCreated([...created,name]);setProjectName("");setModal(false);showToast(`${name} added to the demo project list.`)}else{setModal(false);showToast("Saved to the demo workspace.")}}}><label className="field-label">{section==="Team & Users"?"Email address":"Name"}<input required autoFocus value={projectName} onChange={e=>setProjectName(e.target.value)} placeholder={section==="Team & Users"?"teammate@company.com":"e.g. Customer Portal"}/></label><label className="field-label">{section==="Team & Users"?"Role":"Description"}{section==="Team & Users"?<select><option>Developer</option><option>Project Manager</option><option>Tester</option><option>Viewer</option></select>:<textarea placeholder="What is this work about?" rows={3}/>}</label>{(section==="Projects"||section==="Dashboard")&&<label className="field-label">Project type<select><option>Web application</option><option>API / Service</option><option>Mobile application</option><option>Platform</option></select></label>}<div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(false)}>Cancel</button><button type="submit" className="button primary"><Plus size={14}/>{section==="Team & Users"?"Send invitation":"Create"}</button></div></form></Modal>}</div>
}
